from qiskit import QuantumCircuit
from qiskit.quantum_info import Statevector


# Let's put qubit 1 in the |+> state and qubit 0 in |0> (target to copy to)
qc_attempt = QuantumCircuit(2)
qc_attempt.h(1)       
qc_attempt.cx(1, 0)   # clone using CNOT 

#state generated by the quantum circuit
actual_state = Statevector.from_instruction(qc_attempt)

#Define what a successful clone should look like: |+> tensor_product with |+>
plus_state = Statevector.from_label("+")
expected_clone = plus_state.tensor(plus_state)


print("the state actually generated by cnot",actual_state.draw("text"))

print("\nexpected state",expected_clone.draw("text"))

print("\nAre the actual state and the cloned state equal?", actual_state == expected_clone)